def solve(grid):
    # Find the two non‑zero colours (the background is 0)
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    if len(counts) != 2:
        # If the input does not contain exactly two non‑zero colours,
        # we cannot apply the rule – return a 3×3 grid of zeros.
        return [[0,0,0],[0,0,0],[0,0,0]]

    # The colour that occurs more often is the “shape”, the other is the “item”.
    shape_colour = max(counts, key=counts.get)
    item_colour = min(counts, key=counts.get)

    # Bounding box of the shape colour
    min_r = max_r = min_c = max_c = None
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == shape_colour:
                if min_r is None:
                    min_r = max_r = r
                    min_c = max_c = c
                else:
                    if r < min_r: min_r = r
                    if r > max_r: max_r = r
                    if c < min_c: min_c = c
                    if c > max_c: max_c = c

    if min_r is None:   # shape not found – should not happen
        return [[0,0,0],[0,0,0],[0,0,0]]

    height = max_r - min_r + 1
    width  = max_c - min_c + 1

    # Divide the bounding box into 3×3 equal (or nearly equal) parts.
    # Extra rows/columns are given to the bottom/rightmost segments.
    row_seg = [height // 3] * 3
    for i in range(height % 3):
        row_seg[2 - i] += 1

    col_seg = [width // 3] * 3
    for i in range(width % 3):
        col_seg[2 - i] += 1

    # Build the 3×3 output grid
    out = [[0,0,0] for _ in range(3)]

    row_start = min_r
    for i in range(3):
        row_end = row_start + row_seg[i]
        col_start = min_c
        for j in range(3):
            col_end = col_start + col_seg[j]

            # Check whether the shape colour occurs in this sub‑rectangle
            found = False
            for r in range(row_start, row_end):
                for c in range(col_start, col_end):
                    if grid[r][c] == shape_colour:
                        found = True
                        break
                if found:
                    break

            if found:
                out[i][j] = item_colour
            else:
                out[i][j] = 0

            col_start = col_end
        row_start = row_end

    return out

